#!/usr/bin/env node
/**
 * Bundle @lynx-js/web-core's in_shadow.css (and its @import chain through
 * @lynx-js/web-elements) into one flat file. Webpack does not honor Vite's
 * `*.css?inline` import, so LynxViewInstance otherwise injects a content-hash
 * stub into the shadow root and Lynx flex layout breaks.
 *
 * Usage: node scripts/lynx-shadow-css-bundle.mjs
 */

import {
  existsSync,
  mkdirSync,
  readFileSync,
  writeFileSync,
} from "node:fs";
import { createRequire } from "node:module";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, "..");
const OUT = join(ROOT, "systems/lynx-apps/lib/lynx-shadow.bundle.css");
const require = createRequire(import.meta.url);

const IMPORT_RE = /@import\s+(?:url\(\s*)?['"]([^'"]+)['"]\s*\)?\s*;/g;

function resolveImport(fromFile, spec) {
  if (spec.startsWith(".") || spec.startsWith("/")) {
    return resolve(dirname(fromFile), spec);
  }
  // package subpath, e.g. @lynx-js/web-elements/index.css
  return require.resolve(spec, { paths: [dirname(fromFile), ROOT] });
}

/** @type {Set<string>} */
const seen = new Set();

function bundle(file) {
  const abs = resolve(file);
  if (seen.has(abs)) return "";
  seen.add(abs);
  if (!existsSync(abs)) {
    throw new Error(`Missing CSS: ${abs}`);
  }
  let src = readFileSync(abs, "utf8");
  let out = "";
  let last = 0;
  for (const match of src.matchAll(IMPORT_RE)) {
    out += src.slice(last, match.index);
    const spec = match[1];
    const resolved = resolveImport(abs, spec);
    out += `/* << ${spec} */\n`;
    out += bundle(resolved);
    out += `/* >> ${spec} */\n`;
    last = match.index + match[0].length;
  }
  out += src.slice(last);
  return out;
}

function main() {
  // `css/in_shadow.css` is not in package exports — resolve via package root.
  const pkgJson = require.resolve("@lynx-js/web-core/package.json", {
    paths: [ROOT],
  });
  const entry = join(dirname(pkgJson), "css/in_shadow.css");
  const css = `/* Auto-generated by scripts/lynx-shadow-css-bundle.mjs — do not edit */\n${bundle(entry)}\n`;
  mkdirSync(dirname(OUT), { recursive: true });
  writeFileSync(OUT, css);
  console.log(`→ ${OUT} (${css.length} bytes, ${seen.size} files)`);
}

main();
